package au.com.roningroup.patrollink;
final class CapturePager {static final String SCRIPT="(function(advance){\n const visible=e=>{for(let p=e;p&&p.nodeType===1;p=p.parentElement){const s=getComputedStyle(p);if(s.display==='none'||s.visibility==='hidden')return false;}return !!(e.offsetWidth||e.offsetHeight||e.getClientRects().length);};\n const ids=Array.from(new Set(Array.from(document.querySelectorAll('a,td,span,label,[data-issue-id]')).map(e=>String(e.textContent||'').trim()).filter(t=>/^\\d{7,14}$/.test(t)))).sort();\n const current=Array.from(document.querySelectorAll('.rgCurrentPage,[aria-current=\"page\"],.pagination .active')).map(e=>e.textContent.trim()).join('|');\n const candidates=Array.from(document.querySelectorAll('a,button,input[type=\"button\"],input[type=\"submit\"]')).filter(e=>{\n  if(!visible(e)||e.disabled||e.getAttribute('aria-disabled')==='true'||/disabled/i.test(e.className))return false;\n  const text=String(e.innerText||e.value||'').trim().toLowerCase(),name=String(e.getAttribute('aria-label')||e.title||'').trim().toLowerCase();\n  if(!/^(next|next page|nextpage|>|›)$/.test(text)&&!/^(next|next page|nextpage)$/.test(name)&&!/rgPageNext/i.test(e.className))return false;\n  if(/last|delete|edit|save|submit/i.test(name+' '+text+' '+e.id+' '+e.className))return false;\n  const href=e.getAttribute('href')||'',onclick=e.getAttribute('onclick')||'';\n  if(/delete|edit|save|remove|create/i.test(href+' '+onclick))return false;\n  if(/^javascript:/i.test(href)&&!/__doPostBack|Page\\$Next|Page\\$\\d+/i.test(href))return false;\n  if(href&&!/^javascript:|^#/.test(href)){try{let u=new URL(href,document.baseURI);if(u.origin!==location.origin||!/\\/Monitor\\.aspx$/i.test(u.pathname)||u.username||u.password)return false;}catch{return false;}}\n  return true;\n });\n const fingerprint=ids.join(',')+'#'+current;\n const result={fingerprint,rows:ids.length,next:candidates.length===1};\n if(advance&&candidates.length===1){candidates[0].click();result.clicked=true;}\n return result;\n})";private CapturePager(){}}
